# region: emit
def emit(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: fold
def fold(xs, offset=-1):
    return [v + offset for v in xs]

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: render
def render(xs):
    return [v * v for v in xs[1:]]

# region: intake
def intake(xs, cut=3):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: digest
def digest(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return digest(intake(render(gather(fold(emit(raw))))))

